private string GetExportColumnCaption(BandedGridColumn gcol)
{
    if (gcol.Caption == "Xếp loại")
        return "Xếp<br/>loại";
    if (gcol.Caption == "Ngày sinh")
        return "Ngày<br/>sinh";
    if (gcol.Caption == "Giới tính")
        return "Giới<br/>tính";
    return gcol.Caption;
}

private string GetExportColumnStyle(string strFieldName, bool bolIsHeader)
{
    if (strFieldName == "StudentFirstName")
        return " style='text-align:left; border-right:none; min-width:80px' ";
    if (strFieldName == "StudentLastName")
        return " style='text-align:left; border-left:none' ";
    if (strFieldName == "StudentCode")
        return " style='min-width:55px; white-space:nowrap' ";
    if (strFieldName == "BirthDateText")
        return " style='min-width:72px; white-space:nowrap' ";
    if (strFieldName == "GenderText")
        return " style='min-width:38px; white-space:nowrap' ";
    if (strFieldName == "EthicLevel" || strFieldName == "LearningLevel")
        return " style='min-width:35px' ";
    if (strFieldName.Contains("Mark") || strFieldName.Contains("Exam") || strFieldName.Contains("Summary")
        || strFieldName.Contains("TestAverage") || strFieldName.Contains("OtherFinal") || strFieldName.Contains("LearningLevel_"))
        return bolIsHeader ? " class='col-narrow'" : " class='col-narrow'";
    return "";
}

private string RowsToHTML(List<BandedGridColumn> lstColumns)
{
    string str = "";
    int n = gvData.RowCount;
    for (int i = n - 1; i >= 0; i--)
    {
        DataRow drw = gvData.GetDataRow(i);
        string strRow = "";
        foreach (BandedGridColumn gcol in lstColumns)
        {
            string strColumn = gcol.FieldName;
            string strStyle = GetExportColumnStyle(strColumn, false);
            string strValue = drw[gcol.FieldName].ToString();
            if (strValue.Length < 1)
                strValue = "&nbsp;";
            if (strValue == "-1")
                strValue = "M";

            strRow += "<td" + strStyle + ">" + strValue + "</td>";
        }
        strRow = "<tr>" + strRow + "</tr>\r\n";
        str = strRow + str;
    }
    return str;
}

private string GetExportColumnCaptionOnly(BandedGridColumn gcol)
{
    return GetExportColumnCaption(gcol);
}

private string GetExportHeaderCell(BandedGridColumn gcol)
{
    return "<td" + GetExportColumnStyle(gcol.FieldName, true) + ">" + GetExportColumnCaption(gcol) + "</td>";
}

